  // src/signal_processing/voice.js
  function attachVoiceInput({ button, input: input2, form, status }) {
    const Recognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!Recognition) {
      button.disabled = true;
      button.title = "Speech recognition is unavailable in this browser";
      return { stop() {
      } };
    }
    const recognition = new Recognition();
    recognition.lang = "ar-EG";
    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.maxAlternatives = 1;
    let listening = false;
    recognition.onresult = (event2) => {
      const transcript = event2.results[0]?.[0]?.transcript?.trim();
      if (!transcript) return;
      input2.value = transcript;
      status.textContent = `Heard: ${transcript}`;
      form.requestSubmit();
    };
    recognition.onerror = (event2) => {
      status.textContent = `Microphone: ${event2.error}`;
    };
    recognition.onend = () => {
      listening = false;
      button.textContent = "Speak";
      button.setAttribute("aria-pressed", "false");
    };
    button.addEventListener("click", () => {
      if (listening) {
        recognition.stop();
        return;
      }
      try {
        recognition.start();
        listening = true;
        button.textContent = "Listening\u2026";
        button.setAttribute("aria-pressed", "true");
      } catch (error) {
        status.textContent = `Microphone: ${error.message}`;
      }
    });
    return { stop: () => listening && recognition.stop() };
  }

  // src/ui/phone.js
  function mountPhone({ onDestination, getWorld, getPlaces }) {
    const toggle = document.getElementById("phoneToggleBtn"), panel = document.getElementById("inGamePhone");
    const input2 = document.getElementById("destinationInput"), status = document.getElementById("phoneStatus");
    const form = document.getElementById("destinationForm"), submit = form.querySelector('button[type="submit"]');
    const modelStatus = document.getElementById("phoneModelStatus");
    const voice = attachVoiceInput({
      button: document.getElementById("voiceBtn"),
      input: input2,
      form,
      status
    });
    let history = [], pending = null, generation = 0;
    async function health() {
      try {
        const response = await fetch("/api/nlp/health", {
          signal: AbortSignal.timeout(4e3)
        });
        const data = await response.json();
        modelStatus.textContent = response.ok && data.ready ? "Local NLP model ready \xB7 experimental" : "NLP model offline. Choose a place below.";
      } catch {
        modelStatus.textContent = "NLP model offline. Choose a place below.";
      }
    }
    toggle.addEventListener("click", () => {
      panel.hidden = !panel.hidden;
      toggle.setAttribute("aria-expanded", String(!panel.hidden));
      if (!panel.hidden) {
        document.getElementById("inspectorPanel").hidden = true;
        document.getElementById("inspectorBtn").setAttribute("aria-expanded", "false");
        document.getElementById("settingsPanel").hidden = true;
        document.getElementById("settingsBtn").setAttribute("aria-expanded", "false");
        input2.focus();
        health();
      }
    });
    document.addEventListener("keydown", (event2) => {
      if (event2.key === "Escape" && !panel.hidden) {
        panel.hidden = true;
        toggle.setAttribute("aria-expanded", "false");
        toggle.focus();
      }
    });
    function reset2() {
      voice.stop();
      generation++;
      pending?.abort();
      pending = null;
      history = [];
      submit.disabled = false;
      submit.textContent = "Send";
    }
    form.addEventListener("submit", async (event2) => {
      event2.preventDefault();
      const text6 = input2.value.trim();
      if (!text6 || pending) return;
      const world2 = getWorld(), requestGeneration = generation;
      pending = new AbortController();
      const controller = pending;
      const timeout = setTimeout(() => controller.abort(), 45e3);
      submit.disabled = true;
      submit.textContent = "Understanding\u2026";
      status.textContent = "Interpreting destination\u2026";
      try {
        const response = await fetch("/api/intent", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          signal: controller.signal,
          body: JSON.stringify({
            text: text6,
            environment: world2.environment,
            history: history.slice(-6)
          })
        });
        const result = await response.json();
        if (requestGeneration !== generation || world2 !== getWorld()) return;
        if (!response.ok)
          throw new Error(result.error ?? "Could not interpret request.");
        let reply = result.message;
        if (result.action === "navigate") {
          const place2 = getPlaces().find((p) => p.id === result.destination);
          if (!place2) throw new Error("Destination is unavailable here.");
          reply = onDestination(place2) ? `Navigating to ${place2.name}.` : "No legal route from the current heading.";
        } else if (result.action === "stop") {
          world2.command({ type: "stop" });
          reply = "Braking and cancelling the trip.";
        } else if (result.action === "status") {
          reply = world2.destination ? `Destination: ${world2.destination.name}. Speed: ${Math.round(Math.abs(world2.player.speed) * 3.6)} km/h.` : "No destination selected. Tell me where to go.";
        }
        if ((result.action === "clarify" || result.action === "unsupported") && /[؀-ۿ]/u.test(reply))
          reply = result.action === "unsupported" ? "That request is outside the available destinations and driving controls." : "Please clarify which destination or service you need.";
        status.textContent = reply;
        history.push({ role: "user", text: text6 }, { role: "assistant", text: reply });
        history = history.slice(-6);
        input2.value = "";
      } catch (error) {
        if (requestGeneration === generation)
          status.textContent = error.name === "AbortError" ? "The request timed out. Choose a place or try again." : error.message;
      } finally {
        clearTimeout(timeout);
        if (requestGeneration === generation) {
          pending = null;
          submit.disabled = false;
          submit.textContent = "Send";
        }
      }
    });
    return { reset: reset2 };
  }

